            today = dt.datetime.now(value.tzinfo).date()
        else:
            today = dt.date.today()  # noqa: DTZ011
        value = dt.date(value.year, value.month, value.day)
    except AttributeError:
        # Passed value wasn't date-ish
        return str(value)
